#include <iostream>
 
#define MAX 15
 
using namespace std;
 
int count_divisors(int n) {
    int count = 0;
    for (int i = 1; i * i <= n; ++i) {
        if (!(n % i)) {
            if (i == n / i)
                count++;
            else
                count += 2;
        }
    }
    return count;
}
 
int main() {
    cout << "The first " << MAX << " terms of the sequence are:" << endl;
    for (int i = 1, next = 1; next <= MAX; ++i) {
        if (next == count_divisors(i)) {           
            cout << i << " ";
            next++;
        }
    }
    cout << endl;
    return 0;
}

#include <stdio.h>
 
#define TRUE 1
#define FALSE 0
 
typedef int bool;
 
typedef struct {
    int start, stop, incr;
    const char *comment;
} S;
 
S examples[9] = {
    {-2, 2, 1, "Normal"},
    {-2, 2, 0, "Zero increment"},
    {-2, 2, -1, "Increments away from stop value"},
    {-2, 2, 10, "First increment is beyond stop value"},
    {2, -2, 1, "Start more than stop: positive increment"},
    {2, 2, 1, "Start equal stop: positive increment"},
    {2, 2, -1, "Start equal stop: negative increment"},
    {2, 2, 0, "Start equal stop: zero increment"},
    {0, 0, 0, "Start equal stop equal zero: zero increment"}
};
 
int main() {
    int i, j, c;
    bool empty;
    S s;
    const int limit = 10;
    for (i = 0; i < 9; ++i) {
        s = examples[i];
        printf("%s\n", s.comment);
        printf("Range(%d, %d, %d) -> [", s.start, s.stop, s.incr);
        empty = TRUE;
        for (j = s.start, c = 0; j <= s.stop && c < limit; j += s.incr, ++c) {
            printf("%d ", j);
            empty = FALSE;
        }
        if (!empty) printf("\b");
        printf("]\n\n");
    }
    return 0;
}

def happy(n)
  past = []
  while n!= 1
    n = n.to_s.split("").map{|x| x.to_i**2}.inject(:+)
    return false if past.include?(n)
    past << n
  end
  return true
end

puts (0..500).select{|x| happy(x)}

class Haversine
  R = 6372.8 # In kilometers
  def self.haversine(lat1, lon1, lat2, lon2)
    dLat = Math::PI * (lat2 - lat1) / 180
    dLon = Math::PI * (lon2 - lon1) / 180
    lat1 = Math::PI * lat1 / 180
    lat2 = Math::PI * lat2 / 180

    a = Math.pow(Math.sin(dLat / 2),2) + Math.pow(Math.sin(dLon / 2),2) * Math.cos(lat1) * Math.cos(lat2);
    c = 2 * Math.asin(Math.sqrt(a));
    return R * c;
  end
end

puts Haversine.haversine(36.12, -86.67, 33.94, -118.40)

class CompoundTime
  attr_accessor :w, :d, :h, :m, :s
  def initialize(w, d, h, m, s)
    @w, @d, @h, @m, @s = w, d, h, m, s
  end
  def balance
    @s, @m = @s.divmod(60)
    @m, @h = @m.divmod(60)
    @h, @d = @h.divmod(24)
    @d, @w = @d.divmod(7)
  end
  def to_s
    "#{@w}w #{@d}d #{@h}h #{@m}m #{@s}s"
  end
end
 
ct = CompoundTime.new(0,3,182,345,2412)
puts "Before: #{ct}"
ct.balance
puts "After: #{ct}"

