code:
def compose(*fns)
  ->(*x) { fns.reduce(->(a, b) { ->(c) { a[b[c]] } })[*x] }
end
 
def inv(b)
 !b
end
 
def arr_join(str)
  ->(arr) { arr.join(str) }
end
 
def mk_arr(l, f)
  Array.new(l) { f }
end
 
def sum_arr(arr)
  arr.reduce(0) { |a, b| a + b }
end
 
def sum_to(val)
  ->(arr) { sum_arr(arr) == val }
end
 
def zipper(arr)
  ->(p, c, i) { arr[i]? [*p, c, arr[i]] : [*p, c] }
end
 
def zip(a, b)
  a.reduce(zipper(b)) { |p, c| p }
end
 
def zip_arr(arr)
  ->(a) { zip(a, arr) }
end
 
def has_inner(v)
  ->(arr) { arr[1..-2].index(v) >= 0 }
end
 
def choose(even, odd)
  ->(n) { n % 2 == 0? even : odd }
end
 
def to_bin(f)
  ->(arr) { arr.reduce([]) { |p, c| [*p, *mk_arr(c, f[c])] } }
end
 
def looper(arr, max, acc = [[*arr]], idx = 0)
  if idx!= arr.length
    b = looper(arr, max, acc, idx + 1)[0]
    if b[idx]!= max
      b[idx] = b[idx] + 1
      acc.push(looper(b, max, acc, idx)[0])
    end
  end
  [arr, acc]
end
 
def gap_perms(grp_size, num_gaps, min_val = 0)
  max_val = num_gaps - grp_size * min_val + min_val
  return (grp_size == 2? [[0]] : []) if max_val <= 0
  looper(mk_arr(grp_size, min_val), max_val)[1]
end
 
def test(cells, *blocks)
  grp_size = blocks.length + 1
  num_gaps = cells - sum_arr(blocks)
 
  # Filter functions
  sum_to_trg = sum_to(num_gaps)
  no_inner_zero = compose(inv, has_inner(0))
 
  # Output formatting
  combine = zip_arr([*blocks])
  choices = to_bin(choose(0, 1))
  output = compose(->(x) { puts x }, arr_join(''), choices, combine)
 
  puts "\n#{cells} cells. Blocks: #{blocks}"
  gap_perms(grp_size, num_gaps)
     .select(&no_inner_zero)
     .select(&sum_to_trg)
     .each(&output)
end
 
test(5, 2, 1)
test(5)
test(5, 5)
test(5, 1, 1, 1)
test(10, 8)
test(15, 2, 3, 2, 3)
test(10, 4, 3)
test(5, 2, 3)

