class SOfN
  def initialize(n)
    @n = n
    @sample = []
    @i = 0
  end
 
  def process(item)
    @i += 1
    if @i <= @n
      @sample << item
    elsif rand(@i) < @n
      @sample[rand(@n)] = item
    end
    @sample
  end
end
 
bin = Array.new(10, 0)
(1..100_000).each do
  sOfn = SOfN.new(3)
  (0..8).each { |d| sOfn.process(d) }
  sOfn.process(9).each { |s| bin[s] += 1 }
end
