class CumStdDev
  def initialize
    @n = 0
    @sum = 0.0
    @sum2 = 0.0
  end
 
  def sd(x)
    @n += 1
    @sum += x
    @sum2 += x * x
    Math.sqrt(@sum2 / @n - @sum * @sum / @n / @n)
  end
end
 
